CREATE TABLE "ConstructionBudget" ("id" TEXT NOT NULL,"code" TEXT NOT NULL,"version" INTEGER NOT NULL DEFAULT 1,"workName" TEXT NOT NULL,"clientId" TEXT,"contractorName" TEXT,"technicalLead" TEXT,"address" TEXT,"status" TEXT NOT NULL DEFAULT 'RASCUNHO',"isPublic" BOOLEAN NOT NULL DEFAULT false,"procurementJson" TEXT,"enabledBasesJson" TEXT,"directCost" DECIMAL(14,2) NOT NULL DEFAULT 0,"bdiPercentage" DECIMAL(8,4) NOT NULL DEFAULT 0,"bdiValue" DECIMAL(14,2) NOT NULL DEFAULT 0,"globalTotal" DECIMAL(14,2) NOT NULL DEFAULT 0,"frozenAt" TIMESTAMP(3),"createdBy" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "ConstructionBudget_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "ConstructionBudget_code_version_key" ON "ConstructionBudget"("code","version"); CREATE INDEX "ConstructionBudget_status_createdAt_idx" ON "ConstructionBudget"("status","createdAt");
CREATE TABLE "ConstructionBudgetItem" ("id" TEXT NOT NULL,"budgetId" TEXT NOT NULL,"parentId" TEXT,"kind" TEXT NOT NULL,"hierarchyCode" TEXT NOT NULL,"sortOrder" INTEGER NOT NULL DEFAULT 0,"description" TEXT NOT NULL,"sourceBase" TEXT,"sourceCode" TEXT,"sourceItemId" TEXT,"unit" TEXT,"calculationMemory" TEXT,"quantity" DECIMAL(14,4) NOT NULL DEFAULT 0,"referenceUnitPrice" DECIMAL(14,4) NOT NULL DEFAULT 0,"adoptedUnitPrice" DECIMAL(14,4) NOT NULL DEFAULT 0,"adjustmentPercent" DECIMAL(8,4) NOT NULL DEFAULT 0,"directTotal" DECIMAL(14,2) NOT NULL DEFAULT 0,"differentiatedBdi" DECIMAL(8,4),"bdiValue" DECIMAL(14,2) NOT NULL DEFAULT 0,"totalWithBdi" DECIMAL(14,2) NOT NULL DEFAULT 0,"snapshotJson" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "ConstructionBudgetItem_pkey" PRIMARY KEY ("id"),CONSTRAINT "ConstructionBudgetItem_budgetId_fkey" FOREIGN KEY ("budgetId") REFERENCES "ConstructionBudget"("id") ON DELETE CASCADE,CONSTRAINT "ConstructionBudgetItem_parentId_fkey" FOREIGN KEY ("parentId") REFERENCES "ConstructionBudgetItem"("id") ON DELETE CASCADE); CREATE UNIQUE INDEX "ConstructionBudgetItem_budgetId_hierarchyCode_key" ON "ConstructionBudgetItem"("budgetId","hierarchyCode"); CREATE INDEX "ConstructionBudgetItem_budgetId_parentId_sortOrder_idx" ON "ConstructionBudgetItem"("budgetId","parentId","sortOrder"); CREATE INDEX "ConstructionBudgetItem_sourceBase_sourceCode_idx" ON "ConstructionBudgetItem"("sourceBase","sourceCode");
CREATE TABLE "ConstructionBdi" ("id" TEXT NOT NULL,"budgetId" TEXT NOT NULL,"administration" DECIMAL(8,4) NOT NULL DEFAULT 0,"financial" DECIMAL(8,4) NOT NULL DEFAULT 0,"risk" DECIMAL(8,4) NOT NULL DEFAULT 0,"insuranceGuarantee" DECIMAL(8,4) NOT NULL DEFAULT 0,"profit" DECIMAL(8,4) NOT NULL DEFAULT 0,"cofins" DECIMAL(8,4) NOT NULL DEFAULT 0,"pis" DECIMAL(8,4) NOT NULL DEFAULT 0,"cprb" DECIMAL(8,4) NOT NULL DEFAULT 0,"iss" DECIMAL(8,4) NOT NULL DEFAULT 0,"directPercentage" DECIMAL(8,4),"minReference" DECIMAL(8,4),"maxReference" DECIMAL(8,4),"memoryJson" TEXT,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "ConstructionBdi_pkey" PRIMARY KEY ("id"),CONSTRAINT "ConstructionBdi_budgetId_fkey" FOREIGN KEY ("budgetId") REFERENCES "ConstructionBudget"("id") ON DELETE CASCADE); CREATE UNIQUE INDEX "ConstructionBdi_budgetId_key" ON "ConstructionBdi"("budgetId");
CREATE TABLE "ConstructionSchedulePeriod" ("id" TEXT NOT NULL,"budgetId" TEXT NOT NULL,"period" INTEGER NOT NULL,"startDate" TIMESTAMP(3),"endDate" TIMESTAMP(3),"allocationsJson" TEXT NOT NULL,"percentage" DECIMAL(8,4) NOT NULL DEFAULT 0,"amount" DECIMAL(14,2) NOT NULL DEFAULT 0,CONSTRAINT "ConstructionSchedulePeriod_pkey" PRIMARY KEY ("id"),CONSTRAINT "ConstructionSchedulePeriod_budgetId_fkey" FOREIGN KEY ("budgetId") REFERENCES "ConstructionBudget"("id") ON DELETE CASCADE); CREATE UNIQUE INDEX "ConstructionSchedulePeriod_budgetId_period_key" ON "ConstructionSchedulePeriod"("budgetId","period");
